// ─── File: HiddenClassDemo.java ───
// Single runnable file with multiple top-level package-private classes.
package com.bank.hidden;

import java.lang.invoke.MethodHandles;
import java.math.BigDecimal;
import java.util.logging.*;

public class HiddenClassDemo {
    private static final Logger log = Logger.getLogger(HiddenClassDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Throwable {
        HiddenClassFeeEngine engine = new HiddenClassFeeEngine();
        BigDecimal fee = engine.computeFee(new BigDecimal("1000000"));
        log.info(() -> "Computed fee for Rs.1000000 trade = Rs." + fee);
    }
}

// ─── Would be in rule/FeeRule.java ───
// The hidden class implements this interface. The interface IS visible/normal;
// only the generated implementation class is hidden.
interface FeeRule {
    BigDecimal calculate(BigDecimal amount);
}

// ─── Would be in engine/HiddenClassFeeEngine.java ───
class HiddenClassFeeEngine {
    private static final Logger log = Logger.getLogger(HiddenClassFeeEngine.class.getName());

    BigDecimal computeFee(BigDecimal amount) throws Throwable {
        // 1) Obtain the bytecode for a class implementing FeeRule.
        //    In production a rules engine / ASM / bytecode generator produces this.
        //    Here we load the pre-compiled bytes of a helper class for clarity.
        byte[] classBytes = FeeRuleBytecode.generate();

        // 2) MODERN WAY (JEP 371): define a HIDDEN class via MethodHandles.Lookup.
        //    NESTMATE lets the hidden class share private access with this host.
        MethodHandles.Lookup lookup = MethodHandles.lookup();
        Class<?> hidden = lookup.defineHiddenClass(
                classBytes, /*initialize*/ true,
                MethodHandles.Lookup.ClassOption.NESTMATE).lookupClass();

        log.info(() -> "Defined hidden class: " + hidden.getName());  // name contains '/' + hash
        log.info(() -> "Is hidden? " + hidden.isHidden());            // true

        // 3) The hidden class is NOT resolvable by name:
        try {
            Class.forName(hidden.getName());
            log.severe("Unexpected: hidden class was found by name!");
        } catch (ClassNotFoundException expected) {
            log.info(() -> "As expected, Class.forName cannot find the hidden class by name");
        }

        // 4) Instantiate and invoke through the reference we hold.
        FeeRule rule = (FeeRule) hidden.getConstructor().newInstance();
        BigDecimal fee = rule.calculate(amount);

        // 5) DEPRECATED WAY (do NOT use): sun.misc.Unsafe.defineAnonymousClass(host, bytes, null)
        //    Unsupported, removed in later JDKs. defineHiddenClass replaces it with a
        //    specified lifecycle, nestmate support, and no constant-pool patching.

        // After this method returns and `hidden`/`rule` become unreachable, the
        // hidden class is eligible for independent unloading (metaspace relief).
        return fee;
    }
}

// ─── Helper that returns bytecode of a FeeRule implementation ───
// For demo clarity this delegates to a normal compiled class's bytes; in real
// systems a bytecode library (ASM/ByteBuddy) emits this for high-value trades.
class FeeRuleBytecode {
    static byte[] generate() throws Exception {
        // Load bytes of the bundled PercentFeeRule.class as the "generated" payload.
        String resource = "com/bank/hidden/PercentFeeRule.class";
        try (var in = FeeRuleBytecode.class.getClassLoader().getResourceAsStream(resource)) {
            if (in == null) throw new IllegalStateException("bytecode resource missing");
            return in.readAllBytes();
        }
    }
}

// ─── The payload class whose bytes are used as the hidden class ───
// 0.1% fee on the trade amount, rounded to 2 decimals (banking-safe BigDecimal).
class PercentFeeRule implements FeeRule {
    @Override public BigDecimal calculate(BigDecimal amount) {
        return amount.multiply(new BigDecimal("0.001"))
                     .setScale(2, java.math.RoundingMode.HALF_UP);
    }
}

// ─── Would be in util/BankLogFormatter.java ───
class BankLogFormatter extends java.util.logging.Formatter {
    @Override public String format(java.util.logging.LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
